fs.writeFileSync(path.join(output,'build.json'),JSON.stringify({sources:sourceFiles.map(file=>({path:file,sha256:hash(file)})),products:[host,path.join(nativeInputs,'probe.so'),path.join(nativeInputs,'libadmitted.so'),agent,abi,bridge].map(file=>({path:file,sha256:hash(file)})),commands,compiler:clang,noCargoBuild:true,canonicalSourceChanged:false,providerActivation:false},null,2)+'\n');
