const supplier=require(path.join(launcherRoot,'tests/helpers/android-art-supplier')).componentSupplier(path.resolve(settings.artPayload));
const{layout,prepareMountParents,publishPathMap}=await import(pathToFileURL(path.join(launcherRoot,'src/modules/android/art/layout.mjs')));
