for(const directory of[files,cache,profile])fs.mkdirSync(directory,{recursive:true,mode:0o700});
const config={runtimeRoot:runtime,filesRoot:files,cacheRoot:cache,nativeRoot:nativeInputs,resourcesRoot:output,assetsRoot:supplier.components.image,packageName:'org.maclauncher.bionic.fixture'};
