const isolated=await require(path.join(launcherRoot,'src/modules/android/sandbox')).prepareSandbox({javaPath:path.join(java,'bin/java'),config,configFile,dataRoot:data,userDataDir:profile,processIdentityVersion:1,blockNetwork:true});
