const{frameworkJvmOptions}=require(path.join(launcherRoot,'src/modules/android/jvm-options'));
const args=[...prefix,...isolated.javaArguments,...frameworkJvmOptions,'-XstartOnFirstThread','-Xcheck:jni','-Xmx64m','-XX:+UseSerialGC','-XX:ActiveProcessorCount=2','-XX:+ErrorFileToStderr','-javaagent:'+agent,'-Dbionic.bridge='+host,'-Dbionic.abi='+abi,'-Dbionic.root='+supplier.components.image,'-Dbionic.map='+map,'-Dbionic.runtime='+path.join(data,'kernel'),'-cp',[output,path.join(runtime,'android-host.jar'),path.join(runtime,'android-framework.jar')].join(path.delimiter),'BionicProcessProbe'];
fs.writeFileSync(path.join(output,'invocation.json'),JSON.stringify({command:isolated.command,args,environment,networkBlocked:true,hostMainExecuted:false,originalHostClassLoaded:true,librarySha256:library.sha256,signalBridgeSha256:bridgeSupplier.sha256,jsigSha256:hash(jsig)},null,2)+'\n');
