const result=await new Promise(resolve=>{let error=null,escalation;const signal=name=>{try{process.kill(-child.pid,name);}catch(e){if(e.code!=='ESRCH')throw e;}};const timer=setTimeout(()=>{error='Bounded packet CPU control exceeded20seconds';signal('SIGTERM');escalation=setTimeout(()=>signal('SIGKILL'),1000);},20000);child.once('error',e=>{error=e.message;});child.once('close',(code,signal)=>{clearTimeout(timer);if(escalation)clearTimeout(escalation);resolve({pid:child.pid,code,signal,error});});});
const record={...result,finishedAt:new Date().toISOString(),stdout:fs.readFileSync(path.join(output,'stdout.log'),'utf8'),stderr:fs.readFileSync(path.join(output,'stderr.log'),'utf8'),librarySha256:library.sha256,signalBridgeSha256:bridgeSupplier.sha256,privatePacketComponent:true,productionLoaderActivated:false};
fs.writeFileSync(path.join(output,'RESULT.json'),JSON.stringify(record,null,2)+'\n');console.log(JSON.stringify(record));
if(result.code||result.signal||result.error||!/^PASS ordinary Darwin Java generic AAPCS64 packet /m.test(record.stdout))process.exitCode=1;
